import { Alert, Button, Checkbox, Flex, type FormInstance, Input, Typography } from 'antd';
import { useEffect, useRef, useState } from 'react';

import { generateSql, runLlmFeature, type SqlGenerationResponse } from '../../api/llm';
import { errorMessage, fetchFailure } from '../../utils/errors';
import { CUSTOM_SQL_QUERY_KEY } from './customSql';

/** Server-side cap on the description (`llm_sqlgen.MAX_DESCRIPTION_CHARS`); refused, never clipped. */
const MAX_DESCRIPTION = 2000;

type GenState =
  | { status: 'idle' }
  | { status: 'running' }
  | { status: 'done'; result: SqlGenerationResponse }
  | { status: 'failed'; error: string }
  | { status: 'unavailable'; reason: string };

/**
 * Natural-language → custom SQL (#1845, ADR 0042). Generation never creates a check: the result
 * lands in the editor below, where the same validator, dry-run and save apply unchanged.
 */
export function SqlGeneratePanel({
  suiteId,
  form,
  disabled = false,
}: {
  suiteId: string;
  form: FormInstance;
  disabled?: boolean;
}) {
  const [description, setDescription] = useState('');
  const [includeProfile, setIncludeProfile] = useState(false);
  const [state, setState] = useState<GenState>({ status: 'idle' });
  const abortRef = useRef<AbortController | null>(null);
  useEffect(() => () => abortRef.current?.abort(), []);

  const onGenerate = async () => {
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    setState({ status: 'running' });
    try {
      const row = await runLlmFeature<SqlGenerationResponse>(
        () =>
          generateSql({
            suite_id: suiteId,
            description: description.trim(),
            include_profile: includeProfile,
          }),
        { signal: controller.signal },
      );
      if (controller.signal.aborted) return;
      if (row.status === 'succeeded' && row.response) {
        form.setFieldValue(['config', CUSTOM_SQL_QUERY_KEY], row.response.sql);
        setState({ status: 'done', result: row.response });
      } else {
        setState({ status: 'failed', error: row.error ?? 'the generation failed without a reason' });
      }
    } catch (err) {
      if (controller.signal.aborted) return;
      const failure = fetchFailure(err);
      if (failure.status === 409) {
        setState({ status: 'unavailable', reason: failure.message });
      } else {
        setState({ status: 'failed', error: errorMessage(err) });
      }
    }
  };

  const tooLong = description.length > MAX_DESCRIPTION;
  const canGenerate = !disabled && description.trim().length > 0 && !tooLong;

  return (
    <Flex vertical gap={8} data-testid="sql-generate-panel">
      <Typography.Text strong>Generate from a description</Typography.Text>
      <Typography.Text type="secondary" style={{ fontSize: 12 }}>
        Describe the rule in plain language. The model sees the target&apos;s column names (plus
        null and distinct counts if you include the profile), never rows. Its SQL passes the same
        validator as hand-written SQL, lands in the editor below, and is not saved until you
        dry-run and create the check.
      </Typography.Text>
      <Input.TextArea
        aria-label="Rule description"
        value={description}
        onChange={(e) => setDescription(e.target.value)}
        placeholder="e.g. No order may have a negative quantity or a unit price of zero"
        autoSize={{ minRows: 2, maxRows: 5 }}
        disabled={disabled || state.status === 'running'}
        status={tooLong ? 'error' : undefined}
      />
      {tooLong && (
        <Typography.Text type="danger" style={{ fontSize: 12 }}>
          Keep the description under {MAX_DESCRIPTION} characters — it is refused, not clipped.
        </Typography.Text>
      )}
      <Flex align="center" gap={12} wrap>
        <Button
          type="primary"
          ghost
          onClick={onGenerate}
          loading={state.status === 'running'}
          disabled={!canGenerate}
        >
          Generate SQL
        </Button>
        <Checkbox
          checked={includeProfile}
          onChange={(e) => setIncludeProfile(e.target.checked)}
          disabled={disabled || state.status === 'running'}
        >
          Include column profile
        </Checkbox>
        {state.status === 'running' && (
          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
            Generating on the worker — a local model can take a minute…
          </Typography.Text>
        )}
      </Flex>
      {state.status === 'done' && (
        <Alert
          type="success"
          showIcon
          title="SQL generated — review it in the editor, then dry-run"
          description={state.result.explanation || undefined}
          data-testid="sql-generate-result"
        />
      )}
      {state.status === 'failed' && (
        <Alert type="error" showIcon title="Generation failed" description={state.error} />
      )}
      {state.status === 'unavailable' && (
        <Alert
          type="info"
          showIcon
          title="AI generation is not enabled on this workspace"
          description={state.reason}
        />
      )}
    </Flex>
  );
}

import { Alert, App, Button, Drawer, Empty, Flex, List, Space, Tag, Typography } from 'antd';
import { useEffect, useRef, useState } from 'react';

import {
  type CheckSuggestion,
  type CheckSuggestionsResponse,
  runLlmFeature,
  suggestChecks,
} from '../../api/llm';
import { type CheckCreate, createCheck } from '../../api/suites';
import { errorMessage, fetchFailure } from '../../utils/errors';
import { DimensionTag } from '../checks/checkBadges';

const FRESHNESS_TYPE = 'monitor:freshness';

/** A suggestion → the same `CheckCreate` the editor would submit for it. */
export function suggestionToCheck(s: CheckSuggestion): CheckCreate {
  const isFreshness = s.expectation_type === FRESHNESS_TYPE;
  return {
    name: s.name,
    kind: isFreshness ? 'freshness' : 'expectation',
    expectation_type: s.expectation_type,
    config: s.config,
    dimension: s.dimension ?? undefined,
    fail_threshold: isFreshness ? (s.fail_threshold_hours ?? null) : null,
  };
}

type SuggestState =
  | { status: 'running' }
  | { status: 'done'; result: CheckSuggestionsResponse }
  | { status: 'failed'; error: string }
  | { status: 'unavailable'; reason: string };

/**
 * Profiler-driven check suggestions (#1845, ADR 0042). Every suggestion already passed the
 * `create_check` validator server-side; nothing is created until the user adds it here.
 */
export function SuggestChecksDrawer({
  suiteId,
  open,
  onClose,
  onAdded,
}: {
  suiteId: string;
  open: boolean;
  onClose: () => void;
  /** Called after each successful add so the checks list refetches. */
  onAdded: () => void;
}) {
  return (
    <Drawer title="Suggested checks" open={open} onClose={onClose} size={640} destroyOnHidden>
      {open && <SuggestBody suiteId={suiteId} onAdded={onAdded} />}
    </Drawer>
  );
}

function SuggestBody({ suiteId, onAdded }: { suiteId: string; onAdded: () => void }) {
  const { message } = App.useApp();
  const [state, setState] = useState<SuggestState>({ status: 'running' });
  const [added, setAdded] = useState<Set<number>>(new Set());
  const [adding, setAdding] = useState<Set<number>>(new Set());
  const abortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    abortRef.current = controller;
    (async () => {
      try {
        const row = await runLlmFeature<CheckSuggestionsResponse>(() => suggestChecks(suiteId), {
          signal: controller.signal,
        });
        if (controller.signal.aborted) return;
        if (row.status === 'succeeded' && row.response) {
          setState({ status: 'done', result: row.response });
        } else {
          setState({
            status: 'failed',
            error: row.error ?? 'the suggestion run failed without a reason',
          });
        }
      } catch (err) {
        if (controller.signal.aborted) return;
        const failure = fetchFailure(err);
        if (failure.status === 409) setState({ status: 'unavailable', reason: failure.message });
        else setState({ status: 'failed', error: errorMessage(err) });
      }
    })();
    return () => controller.abort();
  }, [suiteId]);

  const add = async (index: number, s: CheckSuggestion) => {
    setAdding((prev) => new Set(prev).add(index));
    try {
      await createCheck(suiteId, suggestionToCheck(s));
      setAdded((prev) => new Set(prev).add(index));
      message.success(`${s.name}: added`);
      onAdded();
    } catch (err) {
      message.error(`Could not add “${s.name}”: ${errorMessage(err)}`);
    } finally {
      setAdding((prev) => {
        const next = new Set(prev);
        next.delete(index);
        return next;
      });
    }
  };

  if (state.status === 'running') {
    return (
      <Flex vertical gap={8}>
        <Typography.Text>Profiling the target and asking the model…</Typography.Text>
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          The model sees column names and masked statistics — including each non-sensitive
          column&apos;s most frequent values — never rows. A local model can take a minute.
        </Typography.Text>
      </Flex>
    );
  }
  if (state.status === 'unavailable') {
    return (
      <Alert
        type="info"
        showIcon
        title="AI suggestions are not enabled on this workspace"
        description={state.reason}
      />
    );
  }
  if (state.status === 'failed') {
    return <Alert type="error" showIcon title="No suggestions" description={state.error} />;
  }

  const { suggestions, rejected, coverage_warnings: warnings } = state.result;
  const pending = suggestions.map((_, i) => i).filter((i) => !added.has(i));
  const addAll = async () => {
    for (const i of pending) await add(i, suggestions[i]);
  };

  return (
    <Flex vertical gap={16}>
      <Flex justify="space-between" align="center" wrap gap={8}>
        <Typography.Text type="secondary">
          {suggestions.length} suggestion{suggestions.length === 1 ? '' : 's'} passed validation.
          Nothing is created until you add it.
        </Typography.Text>
        <Button
          type="primary"
          size="small"
          onClick={addAll}
          disabled={pending.length === 0 || adding.size > 0}
        >
          Add all remaining
        </Button>
      </Flex>
      {suggestions.length === 0 ? (
        <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No suggestion survived." />
      ) : (
        <List
          dataSource={suggestions.map((s, index) => ({ s, index }))}
          renderItem={({ s, index }) => (
            <List.Item
              actions={[
                added.has(index) ? (
                  <Tag key="added" color="success">
                    Added
                  </Tag>
                ) : (
                  <Button
                    key="add"
                    size="small"
                    loading={adding.has(index)}
                    onClick={() => add(index, s)}
                  >
                    Add
                  </Button>
                ),
              ]}
            >
              <List.Item.Meta
                title={
                  <Space size={6} wrap>
                    <span>{s.name}</span>
                    <Tag>{s.expectation_type}</Tag>
                    <DimensionTag dimension={s.dimension} />
                  </Space>
                }
                description={
                  <Flex vertical gap={2}>
                    <span>{s.rationale}</span>
                    <Typography.Text type="secondary" code style={{ fontSize: 12 }}>
                      {JSON.stringify(s.config)}
                      {s.fail_threshold_hours != null ? ` · fail ≥ ${s.fail_threshold_hours}h` : ''}
                    </Typography.Text>
                  </Flex>
                }
              />
            </List.Item>
          )}
        />
      )}
      {rejected.length > 0 && (
        <Alert
          type="warning"
          showIcon
          title={`${rejected.length} suggestion${rejected.length === 1 ? '' : 's'} rejected by the validator`}
          description={
            <ul style={{ margin: 0, paddingLeft: 18 }}>
              {rejected.map((r, i) => (
                <li key={i}>
                  {r.name ? <strong>{r.name}: </strong> : null}
                  {r.reason}
                </li>
              ))}
            </ul>
          }
        />
      )}
      {warnings.length > 0 && (
        <Alert
          type="info"
          showIcon
          title="A pipeline nearly triggers this suite"
          description={
            <ul style={{ margin: 0, paddingLeft: 18 }}>
              {warnings.map((w, i) => (
                <li key={i}>
                  {w.provider} · {w.pipeline_or_dag_id} runs in {w.run_env ?? '?'} but the binding
                  is for {w.binding_env ?? '?'} — no freshness check was suggested.
                </li>
              ))}
            </ul>
          }
        />
      )}
    </Flex>
  );
}

import { Alert, Button, Flex, List, Tag, Typography } from 'antd';
import { useEffect, useRef, useState } from 'react';

import { getIncidentNarrative, type IncidentNarrativeRead } from '../../api/incidents';
import { generateRcaNarrative, type RcaNarrative, runLlmFeature } from '../../api/llm';
import { useAsyncData } from '../../hooks/useAsyncData';
import { errorMessage, fetchFailure } from '../../utils/errors';
import { formatTimestamp } from '../results/resultsFormat';

const CONFIDENCE_COLORS: Record<string, string> = {
  high: 'green',
  medium: 'gold',
  low: 'default',
};

type GenState =
  | { status: 'idle' }
  | { status: 'running' }
  | { status: 'failed'; error: string }
  | { status: 'unavailable'; reason: string };

/**
 * The root-cause narrative on an incident's evidence card (#1845, #1633). Shows the latest stored
 * narrative when this caller may read it, and lets them request a fresh one. Generation never
 * re-runs the check and never changes the suite.
 */
export function IncidentNarrativeSection({ incidentId }: { incidentId: string }) {
  const { state, reload } = useAsyncData(() => getIncidentNarrative(incidentId));
  const [fresh, setFresh] = useState<{ narrative: RcaNarrative; at: string } | null>(null);
  const [gen, setGen] = useState<GenState>({ status: 'idle' });
  const abortRef = useRef<AbortController | null>(null);
  useEffect(() => () => abortRef.current?.abort(), []);

  const explain = async () => {
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    setGen({ status: 'running' });
    try {
      const row = await runLlmFeature<RcaNarrative>(() => generateRcaNarrative(incidentId), {
        signal: controller.signal,
      });
      if (controller.signal.aborted) return;
      if (row.status === 'succeeded' && row.response) {
        setFresh({ narrative: row.response, at: row.finished_at ?? row.created_at });
        setGen({ status: 'idle' });
        reload();
      } else {
        setGen({ status: 'failed', error: row.error ?? 'the narrative failed without a reason' });
      }
    } catch (err) {
      if (controller.signal.aborted) return;
      const failure = fetchFailure(err);
      if (failure.status === 409) setGen({ status: 'unavailable', reason: failure.message });
      else setGen({ status: 'failed', error: errorMessage(err) });
    }
  };

  const stored: IncidentNarrativeRead | null = state.status === 'ok' ? state.data : null;
  const shown = fresh ?? (stored?.narrative ? { narrative: stored.narrative, at: stored.generated_at ?? '' } : null);

  return (
    <div data-testid="incident-narrative">
      <Flex justify="space-between" align="center" wrap gap={8} style={{ marginBottom: 8 }}>
        <Typography.Title level={5} style={{ margin: 0 }}>
          Root-cause narrative
        </Typography.Title>
        <Button
          size="small"
          type={shown ? 'default' : 'primary'}
          ghost={!shown}
          onClick={explain}
          loading={gen.status === 'running'}
          disabled={gen.status === 'unavailable'}
        >
          {shown ? 'Regenerate' : 'Explain this failure'}
        </Button>
      </Flex>
      {gen.status === 'running' && (
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          Asking the model about this evidence card and the check&apos;s history — nothing is
          fetched from the warehouse. A local model can take a minute…
        </Typography.Text>
      )}
      {gen.status === 'failed' && (
        <Alert type="error" showIcon title="No narrative" description={gen.error} />
      )}
      {gen.status === 'unavailable' && (
        <Alert
          type="info"
          showIcon
          title="AI narratives are not enabled on this workspace"
          description={gen.reason}
        />
      )}
      {shown ? (
        <NarrativeBody narrative={shown.narrative} at={shown.at} />
      ) : (
        gen.status === 'idle' && (
          <Typography.Text type="secondary" italic>
            {stored?.withheld_reason
              ? `A narrative exists but is not shown to you — ${stored.withheld_reason}.`
              : 'None generated yet — narratives are on demand, never automatic.'}
          </Typography.Text>
        )
      )}
    </div>
  );
}

function NarrativeBody({ narrative, at }: { narrative: RcaNarrative; at: string }) {
  return (
    <Flex vertical gap={10}>
      <Typography.Paragraph style={{ margin: 0 }}>{narrative.summary}</Typography.Paragraph>
      {narrative.ranked_hypotheses.length > 0 && (
        <List
          size="small"
          header={<Typography.Text strong>Ranked hypotheses</Typography.Text>}
          dataSource={narrative.ranked_hypotheses}
          renderItem={(h, i) => (
            <List.Item>
              <Flex vertical gap={4}>
                <span>
                  {i + 1}. {h.cause}
                </span>
                <Flex gap={4} wrap>
                  <Tag color={CONFIDENCE_COLORS[h.confidence] ?? 'default'}>{h.confidence}</Tag>
                  {h.evidence_refs.map((ref) => (
                    <Tag key={ref}>{ref}</Tag>
                  ))}
                </Flex>
              </Flex>
            </List.Item>
          )}
        />
      )}
      {narrative.blind_spots.length > 0 && (
        <Alert
          type="warning"
          showIcon
          title="What this evidence could not see"
          description={
            <ul style={{ margin: 0, paddingLeft: 18 }}>
              {narrative.blind_spots.map((b) => (
                <li key={b}>{b}</li>
              ))}
            </ul>
          }
        />
      )}
      {narrative.suggested_next_checks && narrative.suggested_next_checks.length > 0 && (
        <div>
          <Typography.Text strong>Suggested next steps</Typography.Text>
          <ul style={{ margin: '4px 0 0', paddingLeft: 18 }}>
            {narrative.suggested_next_checks.map((s) => (
              <li key={s}>{s}</li>
            ))}
          </ul>
        </div>
      )}
      <Typography.Text type="secondary" style={{ fontSize: 12 }}>
        Generated {at ? formatTimestamp(at) : '—'} · computed from the stored evidence and the
        check&apos;s result history; hypotheses cite evidence layers, blind spots are DataQ&apos;s.
      </Typography.Text>
    </Flex>
  );
}

