import numpy as np
import pandas as pd

from great_expectations.execution_engine import PandasExecutionEngine
from great_expectations.expectations.core.expect_column_values_to_be_of_type import (
    _native_type_type_map,
)
from great_expectations.expectations.metrics.map_metric_provider import (
    ColumnMapMetricProvider,
    column_condition_partial,
)


class ColumnValuesOfType(ColumnMapMetricProvider):
    condition_metric_name = "column_values.of_type"
    condition_value_keys = ("type_",)

    @column_condition_partial(engine=PandasExecutionEngine)
    def _pandas(cls, column, type_, **kwargs):
        comp_types = []
        try:
            comp_types.append(np.dtype(type_).type)
        except TypeError:
            try:
                pd_type = getattr(pd, type_)
                if isinstance(pd_type, type):
                    comp_types.append(pd_type)
            except AttributeError:
                pass

            try:
                pd_type = getattr(pd.core.dtypes.dtypes, type_)
                if isinstance(pd_type, type):
                    comp_types.append(pd_type)
            except AttributeError:
                pass

        native_type = _native_type_type_map(type_)
        if native_type is not None:
            comp_types.extend(native_type)

        if len(comp_types) < 1:
            raise ValueError(f"Unrecognized numpy/python type: {type_}")  # noqa: TRY003 # FIXME CoP

        return column.map(lambda x: isinstance(x, tuple(comp_types)))

def _check_errored(exception_info: Any) -> tuple[bool, str | None]:
    """Did this expectation raise while being evaluated? (GX `exception_info`)."""
    if not isinstance(exception_info, dict) or not exception_info:
        return False, None
    if "raised_exception" in exception_info:  # flat shape
        return bool(exception_info.get("raised_exception")), exception_info.get("exception_message")
    # keyed-by-metric shape: errored if any metric computation raised
    for entry in exception_info.values():
        if isinstance(entry, dict) and entry.get("raised_exception"):
            return True, entry.get("exception_message")
    return False, None


